#include <iostream>
#include <string>
using namespace std;

class Purse {
public:
    virtual string label() {
        return "普通钱袋";
    }
};

class SavingPurse : public Purse {
public:
    string label() {
        return "攒钱袋";
    }
};

int main() {
    Purse plain;
    SavingPurse saving;

    Purse *shown[2];
    shown[0] = &plain;
    shown[1] = &saving;

    for (int i = 0; i < 2; i++) {
        cout << "第 " << i + 1 << " 只是 " << shown[i]->label() << " 喵" << endl;
    }
    return 0;
}
